dql.script:
parse metadata, "JSON:oi_metadata"
| fieldsAdd gen_ai.operation.kind = if(openinference.span.kind == "CHAIN", "workflow",
      else: if(openinference.span.kind == "TOOL", "tool",
      else: if(openinference.span.kind == "AGENT", "agent",
      else: if(openinference.span.kind == "RETRIEVER", "retrieval",
      else: if(openinference.span.kind == "GUARDRAIL", "guardrail",
      else: "task"))))),
    gen_ai.operation.name = if(openinference.span.kind == "AGENT", "invoke_agent",
      else: if(openinference.span.kind == "TOOL", "execute_tool",
      else: if(isNotNull(embedding.model_name), "embeddings",
      else: gen_ai.operation.name))),
    gen_ai.agent.name = coalesce(agent.name, gen_ai.agent.name, oi_metadata[agent_name], if(openinference.span.kind == "AGENT", span.name)),
    gen_ai.request.model = coalesce(embedding.model_name, reranker.model_name, gen_ai.request.model),
    gen_ai.embeddings.dimension.count = coalesce(embedding.vector_length, gen_ai.embeddings.dimension.count),
    gen_ai.guardrail.name = coalesce(validator_name, gen_ai.guardrail.name),
    ai.observability.source = "openinference"
| fieldsRemove oi_metadata, agent.name, embedding.model_name, embedding.vector_length, reranker.model_name,
    validator_name, input.mime_type, output.mime_type,
    llm.invocation_parameters, llm.token_count.total,
    `llm.token_count.prompt_details.audio`, `llm.token_count.prompt_details.cache_read`,
    `llm.token_count.prompt_details.cache_write`, `llm.token_count.completion_details.audio`,
    `llm.token_count.completion_details.reasoning`,
    `llm.input_messages.0.message.role`, `llm.input_messages.0.message.content`,
    `llm.output_messages.0.message.role`, `llm.output_messages.0.message.content`
